def moving_average(xs, w):
    if w == 0:
        return []

    averages = []
    window = deque()
    current_sum = 0.0

    for i, x in enumerate(xs):
        window.append(x)
        current_sum += x

        if len(window) > w:
            current_sum -= window.popleft()

        if len(window) == w:
            averages.append(current_sum / w)

    return averages
